using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;
public static class CompleteVillage {
 static Vector3 P(float x,float z,float y=0)=>new Vector3(x-60,y,z-32);
 static GameObject root;static Material road;
 static void Path(Vector3 a,Vector3 b,float width){Vector3 d=b-a;var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name="Dirt path";o.transform.SetParent(root.transform);o.transform.position=(a+b)*.5f+Vector3.up*.025f;o.transform.rotation=Quaternion.LookRotation(d);o.transform.localScale=new Vector3(width,.04f,d.magnitude);UnityEngine.Object.DestroyImmediate(o.GetComponent<Collider>());o.GetComponent<Renderer>().sharedMaterial=road;}
 [MenuItem("Vampire Demo/Complete Village Layout")]
 public static void Run(){var s=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueVillageSplitReview.unity");if(!EditorSceneManager.SaveScene(s,"Assets/Demo/Scenes/PrologueVillageLayoutReview.unity",true))throw new Exception("save failed");s=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueVillageLayoutReview.unity");root=new GameObject("Village paths and props");road=new Material(Shader.Find("Universal Render Pipeline/Lit"));road.color=new Color(.24f,.20f,.16f);AssetDatabase.CreateAsset(road,"Assets/Demo/Atmosphere/VillagePathReview.mat");
 Vector3[] route={P(2,29),P(13,29),P(21,25),P(30,25),P(39,29),P(49,26),P(58,33),P(70,33),P(84,32),P(100,29),P(116,27)};for(int i=0;i<route.Length-1;i++)Path(route[i],route[i+1],5);Path(P(13,29),P(13,50),3);Path(P(30,25),P(28,12),3);Path(P(39,29),P(39,34),4);
 var plaza=GameObject.CreatePrimitive(PrimitiveType.Cylinder);plaza.name="Village square";plaza.transform.SetParent(root.transform);plaza.transform.position=P(28,27,.025f);plaza.transform.localScale=new Vector3(14,.025f,11);UnityEngine.Object.DestroyImmediate(plaza.GetComponent<Collider>());plaza.GetComponent<Renderer>().sharedMaterial=road;
 var well=GameObject.CreatePrimitive(PrimitiveType.Cylinder);well.name="Square well placeholder";well.transform.SetParent(root.transform);well.transform.position=P(28,27,.5f);well.transform.localScale=new Vector3(1.5f,.5f,1.5f);
 string[] props={"pf_fence_01_double","pf_barrels_01"};for(int i=0;i<16;i++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Viking Village/Prefabs/Props/"+props[i<10?0:1]+".prefab");if(!prefab)continue;var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.SetParent(root.transform);if(i<5)o.transform.position=P(7+i*5,54);else if(i<10)o.transform.position=P(10+(i-5)*5,6);else o.transform.position=P(18+(i-10)*5,18+(i%2)*17);}
 var veg=GameObject.Find("Forest review - placed vegetation");int hidden=0;if(veg)foreach(Transform t in veg.transform){if(!t.gameObject.activeSelf)continue;Vector3 q=t.position;for(int i=0;i<route.Length-1;i++){Vector3 a=route[i],b=route[i+1];Vector2 ab=new Vector2(b.x-a.x,b.z-a.z),ap=new Vector2(q.x-a.x,q.z-a.z);float k=Mathf.Clamp01(Vector2.Dot(ap,ab)/ab.sqrMagnitude);if((ap-k*ab).magnitude<3.1f){t.gameObject.SetActive(false);hidden++;break;}}}Debug.Log("Road trees hidden "+hidden);
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);Debug.Log("LAYOUT_COMPLETE");}
}
